import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E5%8C%96%E5%AD%A6%E8%A8%88%E7%AE%97%E5%95%8F%E9%A1%8C%E3%81%AE%E8%A7%A3%E3%81%8D%E6%96%B9.html","title":"化学計算問題の解き方","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.8,"words":541},"filePathRelative":"化学計算問題の解き方.md"}`),a={name:`化学計算問題の解き方.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="化学計算問題の解き方" tabindex="-1"><a class="header-anchor" href="#化学計算問題の解き方"><span>化学計算問題の解き方</span></a></h1><p><a href="./化学.html">化学</a></p><p>自分が受験のころにあった以下の本は、もう絶版らしい。 <a href="https://amzn.to/49j2zYe" target="_blank" rel="noopener noreferrer">amazon: モル法 化学計算問題の解き方</a></p><p>だが、この著者が要点を論文にしているpdfが残っている。</p><p><a href="https://www.jstage.jst.go.jp/article/kagakukyouiku/20/6/20_KJ00003480146/_article/-char/ja/" target="_blank" rel="noopener noreferrer">jstage: モル法による高校化学計算の指導事例</a></p><p>これを元に、高校生の甥に要点だけ伝えてみようと思い、その草稿的なメモをここに書いてみる。</p><h2 id="要点" tabindex="-1"><a class="header-anchor" href="#要点"><span>要点</span></a></h2><p>要点は二つ+補助的な1つで合計3つ。</p><p>まずは二つの要点</p><ol><li>単位あたりの量に何単位かを掛ける</li><li>問題をAのモルを出す、AからBのモルを出す、Bのモルから目的の値を出す、に統一する</li></ol><p>これは並列ではなく、1を前提に2がある。</p><p>さらにこれらを補完する事として、単位がある。これが補助的な追加の項目。</p><ul><li>単位を書く、それを解釈して「単位あたりの量」をいろいろ考える</li></ul><p>この三つが基本となる。</p><p>この手法をマスターすると、化学の新しい知識が出てくる都度、それをモル数への計算とモル数からの計算の二つに注目してそこだけ覚えればよい、となる。 そこから先は全て同じ解き方となるので、解けば解くほど同じ事を繰り返すのでちゃんと定着するから、 最初に短時間練習して手法を覚えれば高校生の間ずっと使えるんじゃないか。</p><h2 id="_1-単位あたりの量に何単位かを掛ける" tabindex="-1"><a class="header-anchor" href="#_1-単位あたりの量に何単位かを掛ける"><span>1. 単位あたりの量に何単位かを掛ける</span></a></h2><p>要点その1の単位あたりの量と何単位かを掛ける、について、まずは単位あたりの量を見ていく。</p><h3 id="単位あたりの量を自由に使いこなす" tabindex="-1"><a class="header-anchor" href="#単位あたりの量を自由に使いこなす"><span>単位あたりの量を自由に使いこなす</span></a></h3><p>単位あたりの量、というのは典型的にはモル濃度なのだが、それ以外でもどんな単位でも好きに使えるように訓練する、というのが最初のアイデア。</p><p>例えば100gあたり93円のグラノーラが売っていたとする。 これは100gを単位とした値段になる。 まず1gあたりの値段に直せるようにする。 次に1円あたりの値段に直せるようにする。 この逆数を自由に使えるように訓練する。 また、1gではなく100gも使えるようにする。</p><p>これを他のものでもいくつかやる。 例えば1mol で22.4lの時、1lあたり何モルか？とか。</p><p>比の問題をこの形で解けるように訓練。</p><h3 id="単位を活用する" tabindex="-1"><a class="header-anchor" href="#単位を活用する"><span>単位を活用する</span></a></h3><p>最終的に求めたいものの単位を右辺にまず書く、そしてそれになるように左辺の単位を組み立てる。 単位あたりの量の訓練をしたあとにこれをやると、ほとんど次元解析と立式が同じ作業になることが分かる。</p><h3 id="何単位か、と単位あたりの量の式の固定" tabindex="-1"><a class="header-anchor" href="#何単位か、と単位あたりの量の式の固定"><span>何単位か、と単位あたりの量の式の固定</span></a></h3><p>必ず <code>何単位か？ * 単位あたりの量</code> の順番に立式を固定する。 そしてわからない所は単位だけ書いて空白をあける。</p><p>問題をこの二つを求める事に帰着させて、いつも同じ考え方で考えられるようにする。</p><h2 id="_2-問題をモルを出す事とモルから出すに統一" tabindex="-1"><a class="header-anchor" href="#_2-問題をモルを出す事とモルから出すに統一"><span>2. 問題をモルを出す事とモルから出すに統一</span></a></h2><p>1でいろいろな単位の間を自由に行き来できるようになったら、次はいろいろな計算問題をモルを求める事と、 モルから目的の値を出す事に帰着させて解く事を覚える。 基本的には以下の3ステップになる。</p><ol><li>与えられた量からAのモルを求める</li><li>AのモルからBのモルを求める</li><li>Bのモルから求める量を求める</li></ol><p>そして1と3はほとんど同じ話となる。ので、実質以下の二つとなる</p><ol><li>モルとの換算</li><li>モルからモルを求める</li></ol><p>そして2は比例計算となり、要点1に帰着される。</p><h3 id="モルとの換算" tabindex="-1"><a class="header-anchor" href="#モルとの換算"><span>モルとの換算</span></a></h3><p>そこまで習っている事をモルとの換算としてすべて整理しなおす。 例えば理想気体の状態方程式による体積との換算、溶液の濃度、中和反応、電気分解など。</p><p>これは単位あたりの量に単位を掛ける形にできて、要点1に帰着できる。</p><p>ここで、濃度で割る、も訓練する。</p><h3 id="モルからモルを求める" tabindex="-1"><a class="header-anchor" href="#モルからモルを求める"><span>モルからモルを求める</span></a></h3><p>だいたいは化学反応式などを元に換算する事になるが、 これも比例を要点1の形で書けるように訓練することで、一発で立式できるようにする。</p><p>これを途中式を挟まずに一発で立式出来るよにする事で、 計算問題を一発で立式出来るように出来る。</p><h2 id="たくさん立式だけする" tabindex="-1"><a class="header-anchor" href="#たくさん立式だけする"><span>たくさん立式だけする</span></a></h2><p>一発で立式出来るようになったら、あとは計算問題をたくさん立式する。 立式自体はすぐに終わるので、たくさん繰り返せる。</p>`,42)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};